head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > M > getChildNodes]<br/>Value 값을 사용하여 특정 트리 아이템의 자식 아이템을 객체 배열로 반환합니다.",
    "validation" : [
        "value(필수) 파라미터로 자식 아이템을 조회 하려는 트리 아이템의 Value 값을 설정합니다.",
        "hierarchy(선택) 파라미터로 재귀적으로 모든 자식 아이템을 반환할지 true/false 로 설정합니다.",
        "hierarchy(선택) 파라미터로 미설정 또는 false 설정 시 특정 트리 아이템에 속한 자식 아이템만 반환합니다.",
        "hierarchy(선택) 파라미터로 true 설정 시 재귀적으로 모든 자식 아이템을 반환합니다.",
        "반환값으로 트리 아이템을 객체로 반환합니다.",
        "value 파라미터에 해당하는 트리 아이템이 없으면 undefined 값을 반환합니다.",
        "반환된 객체의 checked 속성값으로 트리 아이템의 CheckBox 선택 상태값을 갖습니다.",
        "반환된 객체의 checkboxDisabled 속성값으로 트리 아이템의 CheckBox 비활성화(disabled) 상태값을 갖습니다.",
        "반환된 객체의 depth 속성값으로 트리 아이템의 Depth(단계)값을 갖습니다.",
        "반환된 객체의 folder 속성값으로 트리 아이템의 확장(false)/축소(true) 상태값을 갖습니다.",
        "트리 아이템이 Leaf 인 경우 반환된 객체의 folder 속성값으로 false 값을 갖습니다.",
        "반환된 객체의 index 속성값으로 트리 아이템의 인덱스값을 갖습니다.",
        "반환된 객체의 label 속성값으로 화면에 표시되는 라벨값이 아닌 트리 아이템의 Label 값을 갖습니다.",
        "반환된 객체의 value 트리 아이템의 Value 값을 갖습니다.",
        "반환된 객체의 parentNode 속성값으로 트리 아이템의 부모 트리 아이템 객체를 갖습니다.",
        "반환된 객체의 childNodes 속성값으로 트리 아이템의 자식 트리 아이템 객체를 배열로 갖습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {            
        showCheckbox : true,            
        hierarchy : true,
    }

    let cList = $c.gcm.createCList(properties);  
    let eList = $c.gcm.createEList(["onclick"]);

    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:treeview ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" dataType="listed" tooltipGroupClass="false" style="width:200px; height:350px;">';
    strTarget += '<w2:itemset nodeset="data:dlt_Item">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<w2:depth ref="depth"></w2:depth>';
    strTarget += '<w2:folder ref=""></w2:folder>';
    strTarget += '<w2:checkbox ref="checkbox"></w2:checkbox>';
    strTarget += '<w2:checkboxDisabled ref="disabled"></w2:checkboxDisabled>';
    strTarget += '<w2:image ref=""></w2:image>';
    strTarget += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:treeview>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "treeview",
        strTarget,
        grp_comp
    );
}



scwin.btn_getChildNodes_onclick = function (e) {   
    let nodes = null;
    let value = Number(par_value.getText());
    let hierarchy = par_hierarchy.getText();

    if (hierarchy == "true")
        hierarchy = true;

    if (hierarchy == "false")
        hierarchy = false;

    if (hierarchy == "")
        nodes = target1.getChildNodes(value);
    else 
        nodes = target1.getChildNodes(value, hierarchy);

    wf_body_bottom.getObj("scwin").setReturnValue("return object : "+ nodes);

    if (nodes.length > 0) {
        for (var i=0; i < nodes.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] checked : "+ nodes[i].checked);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] checkboxDisabled : "+ nodes[0].checkboxDisabled);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] depth : "+ nodes[i].depth);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] folder : "+ nodes[i].folder);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] index : "+ nodes[i].index);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] label : "+ nodes[i].label);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] value : "+ nodes[i].value);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] parentNode.label : "+ nodes[i].parentNode.label);
            wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] childNodes.length : "+ nodes[i].childNodes.length);        
        }
    }
};
